      description = "Excluir Keycloak OAuth y login-actions de LFI/SQLi check"
      preview     = false
      expr        = "request.headers['host'].matches('keycloak\\.(liftit\\.co|(qa|stg)\\.liftit-sandbox\\.com)') && (request.path.matches('/auth/realms/.*/broker/google/endpoint') || request.path.matches('/auth/realms/.*/login-actions/.*'))"
    }
    # WAF-04: Excluir Superset de SQLi/XSS — herramienta BI envía queries SQL en form_data (inherente a su funcionamiento)
    # 28 hits id942100-sqli + 1 hit id941100-xss en 16 días, todos falsos positivos en chart/data y explore_json
    "1046" = {
      action      = "allow"
      description = "Excluir Superset BI de SQLi/XSS check (queries SQL en form_data)"
      preview     = false
      expr        = "request.headers['host'] == 'superset.liftit.co'"
    }
    # WAF-02 MIGRATION: 13 rules migrated from evaluatePreconfiguredExpr to new API with sensitivity 1
    "1030" = {
